// Filtrer uniquement les lignes EN_ATTENTE
const rows = $input.all();
const enAttente = rows.filter(r =>
  (r.json.statut || '').toUpperCase() === 'EN_ATTENTE'
);

if (enAttente.length === 0) {
  throw new Error('STAGING_VIDE: Aucune ligne EN_ATTENTE à traiter');
}

console.log(`REVUE_BATCH: ${enAttente.length} lignes EN_ATTENTE trouvées`);
return enAttente;

const d = $input.first().json;

const FISCAL_CATS = ['PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE','PRIV_AUTO','MIXTE'];
const isFiscal = FISCAL_CATS.includes((d.Categorie || '').toUpperCase());

let fiscalYear = new Date().getFullYear();
try { if (d.Date) fiscalYear = new Date(d.Date).getFullYear(); } catch(e) {}

const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : '_GED_ARCHIVE';

function san(s, max=30) {
  if (!s && s !== 0) return 'INCONNU';
  return String(s).toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]/g,'_').replace(/_{2,}/g,'_')
    .replace(/^_+|_+$/g,'').substring(0, max);
}

const date    = d.Date || new Date().toISOString().split('T')[0];
const emet    = san(d.Emetteur, 25);
const cat     = san(d.Categorie, 20);
const objet   = san(d.Objet || d.Sous_Categorie, 25);
const benef   = san(d.Beneficiaire, 20);
const montant = String(d.Montant_TTC || 0).replace('.','-');

const finalFileName = [date, cat, emet, objet, benef, montant].join('-') + '.pdf';

return [{
  json: {
    ...d,
    _isFiscal:         isFiscal,
    _fiscalYear:       fiscalYear,
    _targetFolderName: targetFolderName,
    _impotsParentId:   $env.GED_IMPOTS_PARENT_ID,
    _archiveFolderId:  $env.GED_ARCHIVE_FOLDER_ID,
    _finalFileName:    finalFileName,
    _originalFileId:   d.File_Id || ''
  }
}];

const mergeData = $('🔎 Résoudre Dossier Cible').first().json;
let folderId = null;

try {
  const c = $('📁 Créer Dossier').first().json;
  if (c.id) folderId = c.id;
} catch(e) {}

if (!folderId) {
  try {
    const f = $('🔍 Chercher Dossier').first().json;
    if (f.files && f.files.length > 0) folderId = f.files[0].id;
  } catch(e) {}
}

if (!folderId) {
  folderId = mergeData._isFiscal
    ? mergeData._impotsParentId
    : mergeData._archiveFolderId;
}

return [{ json: { ...mergeData, _resolvedFolderId: folderId } }];

const d     = $('📌 Résoudre ID Dossier').first().json;
const drive = $('☁️ Upload Renommé').first().json;
const lien  = drive.webViewLink || drive.webContentLink || '';
return [{ json: { ...d, Lien_Drive: lien, _driveLink: lien } }];

// Préparer message Telegram avec boutons catégories
const d = $input.first().json;
const fileId = d.File_Id || '';
const chatId = $env.GED_TELEGRAM_CHAT_ID;

const CATS = [
  'PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE',
  'PRIV_AUTO','MIXTE','PRIV_VIE','PRIV_ENFANTS',
  'ADMIN','IGNORER'
];

const buttons = CATS.map(cat => ([{
  text: cat,
  callback_data: `CAT|${cat}|${fileId}`
}]));

const msg = [
  '⚠️ *Document à valider manuellement*',
  '',
  `📄 *Fichier:* \`${d.File_Name || fileId}\``,
  `🗂️ *Catégorie IA:* ${d.Categorie || '?'}`,
  `⚠️ *Confiance:* ${d.Confiance || '?'}`,
  `💰 *Montant:* ${d.Montant_TTC || 0} $`,
  `📅 *Date:* ${d.Date || '?'}`,
  `🏢 *Émetteur:* ${d.Emetteur || '?'}`,
  d.Raison_Doute ? `\n💬 *Note:* ${d.Raison_Doute}` : '',
  d.Lien_Drive ? `🔗 [Voir le document](${d.Lien_Drive})` : '',
  '',
  '_Choisir la catégorie correcte:_'
].filter(Boolean).join('\n');

return [{
  json: {
    ...d,
    _tgChatId:    chatId,
    _tgMessage:   msg,
    _tgKeyboard:  JSON.stringify({ inline_keyboard: buttons })
  }
}];

const now = new Date().toLocaleString('fr-CA', { timeZone: 'America/Toronto' });
return [{
  json: {
    rapport: `✅ *_REVUE_BATCH terminée*\n🕐 ${now}\n\nToutes les lignes EN_ATTENTE ont été traitées.\n_Vérifier _STAGING pour les documents envoyés en Telegram._`
  }
}];
